def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

n = 4
solutions = []
for x in range(5, 11):
    lhs = x**n + x
    rhs_target = lhs - 2

    if is_power_of_two(rhs_target):
        k = rhs_target.bit_length() - 1
        solutions.append((x, n, k))
    else:
        print(f"For x={x}, x^4 + x - 2 = {rhs_target}, which is not a power of 2.")

if solutions:
    print("Solutions found:")
    for sol in solutions:
        print(sol)
else:
    print("No solutions found for n=4 in the range 5 <= x <= 10.")

